import { describe, it } from 'node:test';
import assert from 'node:assert';
import { load } from 'js-yaml';

describe('proof', () => {
  it('resolves explicitly tagged signed binary integers', () => {
    assert.strictEqual(load('!!int -0b11'), -3);
    assert.strictEqual(load('!!int +0b101'), 5);
    assert.throws(() => load('!!int x0b1'), /cannot resolve a node/);
  });
});

